import sys
from collections import deque

N = int(sys.stdin.read().split()[0])
dist = {N: 0}
q = deque([N])
while q:
    h = q.popleft()
    if h == 0:
        break
    nxt = [h - 1]
    d = 2
    while d * d <= h:
        if h % d == 0:
            nxt.append(h // d)  # h = (h // d) * d with h // d >= d > 1
        d += 1
    for x in nxt:
        if x not in dist:
            dist[x] = dist[h] + 1
            q.append(x)
print(dist[0])

